"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

export default function Login() {
  const router = useRouter();

 useEffect(() => {
  const handleGoogleLogin = async () => {
    const params = new URLSearchParams(window.location.search);
    const token = params.get("token");

    if (!token) return;

    try {
      // Save Google JWT
      localStorage.setItem("token", token);

      // Get logged-in user from backend
      const response = await fetch(
        "https://agriconnect-x8no.onrender.com/me",
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      if (!response.ok) {
        console.error("Google user fetch failed:", response.status);
        alert("Google Login failed");
        return;
      }

      const user = await response.json();

      console.log("GOOGLE USER:", user);

      // Save user
      localStorage.setItem("user", JSON.stringify(user));

      alert("Google Login Successful!");

      // Remove token from URL
      window.history.replaceState({}, document.title, "/login");

      router.push("/dashboard");

    } catch (error) {
      console.error("Google Login Error:", error);
      alert("Something went wrong with Google Login");
    }
  };

  handleGoogleLogin();
}, [router]);
const [form, setForm] = useState({
  email: "",
  password: "",
 });

  const handleLogin = async () => {
  try {
const response = await fetch("https://agriconnect-x8no.onrender.com/login", {
        method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(form),
    });

    const data = await response.json();
console.log("Login Response:", data);
console.log("USER:", data.user);
console.log("TOKEN:", !!data.token);
if (response.ok) {
  localStorage.setItem("token", data.token);

  if (data.user) {
    localStorage.setItem("user", JSON.stringify(data.user));
  }

  alert("Login Successful!");

  router.push("/dashboard");
}
else {
  alert(data.message);
}

  } catch (error) {
    console.error(error);
    alert("Server Error");
  }
};

  return (
    <main className="min-h-screen flex items-center justify-center bg-green-50">

      <div className="bg-black text-white p-8 rounded-xl shadow w-96">

        <h1 className="text-3xl font-bold text-center">
          Login
        </h1>

        <p className="text-center text-gray-300 mt-2">
          Login to access your AgriConnect account
        </p>

        <input
  type="email"
  placeholder="Email"
  value={form.email}
  onChange={(e) =>
    setForm({ ...form, email: e.target.value })
  }
  className="w-full mt-6 p-2 border border-gray-600 bg-gray-900 text-white rounded"
/>

   <input
  type="password"
  placeholder="Password"
  value={form.password}
  onChange={(e) =>
    setForm({ ...form, password: e.target.value })
  }
  className="w-full mt-4 p-2 border border-gray-600 bg-gray-900 text-white rounded"
/>     

        <button
          onClick={handleLogin}
          className="w-full mt-6 bg-green-500 hover:bg-green-600 text-black font-bold py-2 rounded"
        >
          Login
        </button>

        <a href="https://agriconnect-x8no.onrender.com/auth/google">
  <button className="w-full mt-3 bg-blue-600 hover:bg-blue-700 text-white font-bold py-2 rounded">
    Continue with Google
  </button>
</a>
        
     <p className="text-center mt-4 text-gray-300">
  Don't have an account?{" "}
  <span
    onClick={() => router.push("/register")}
    className="text-green-400 cursor-pointer"
  >
    Register
  </span>
</p>

      </div>
    </main>
  );
}

